# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> STATIC
_static_verify_encryption() {
    cat <<-'ARGCEOF'
	AES-128	128-bit AES encryption
	AES-256	256-bit AES encryption (recommended)
ARGCEOF
}

_static_create_layout() {
    cat <<-'ARGCEOF'
	MBRSPUD	Single partition - Master Boot Record Partition Map
	SPUD	Single partition - Apple Partition Map
	UNIVERSAL CD	CD/DVD
	NONE	No partition map
	GPTSPUD	Single partition - GUID Partition Map
	SPCD	Single partition - CD/DVD
	UNIVERSAL HD	Hard disk
	ISOCD	Single partition - CD/DVD with ISO data
ARGCEOF
}

_static_create_fs() {
    cat <<-'ARGCEOF'
	UDF	Universal Disk Format (UDF)
	MS-DOS FAT12	MS-DOS (FAT12)
	MS-DOS	MS-DOS (FAT)
	MS-DOS FAT16	MS-DOS (FAT16)
	MS-DOS FAT32	MS-DOS (FAT32)
	HFS+	Mac OS Extended
	Case-sensitive HFS+	Mac OS Extended (Case-sensitive)
	Case-sensitive Journaled HFS+	Mac OS Extended (Case-sensitive, Journaled)
	Journaled HFS+	Mac OS Extended (Journaled)
	ExFAT	ExFAT
	Case-sensitive APFS	APFS (Case-sensitive)
	APFS	APFS
ARGCEOF
}

_static_create_type() {
    cat <<-'ARGCEOF'
	SPARSEBUNDLE	sparse bundle disk image
	SPARSE	sparse disk image
	UDIF	read/write disk image
	UDTO	DVD/CD master
ARGCEOF
}

_static_create_srcowners() {
    cat <<-'ARGCEOF'
	on	enable owners on source
	off	disable owners on source
	any	leave owners state on source unchanged
	auto	enable owners if source is a volume
ARGCEOF
}

_static_create_format() {
    cat <<-'ARGCEOF'
	UDRO	read-only
	UDCO	compressed (ADC)
	UDZO	compressed
	UDBZ	compressed (bzip2), deprecated
	ULFO	compressed (lzfse)
	ULMO	compressed (lzma)
	UFBI	entire device
	IPOD	iPod image
	UDSB	sparsebundle
	UDSP	sparse
	UDRW	read/write
	UDTO	DVD/CD master
	UNIV	hybrid image (HFS+/ISO/UDF)
	SPARSEBUNDLE	sparse bundle disk image
	SPARSE	sparse disk image
	UDIF	read/write disk image
ARGCEOF
}

_static_create_encryption() {
    cat <<-'ARGCEOF'
	AES-128	128-bit AES encryption
	AES-256	256-bit AES encryption (recommended)
ARGCEOF
}

_static_compact_encryption() {
    cat <<-'ARGCEOF'
	AES-128	128-bit AES encryption
	AES-256	256-bit AES encryption (recommended)
ARGCEOF
}

_static_convert_format() {
    cat <<-'ARGCEOF'
	UDRO	read-only
	UDCO	compressed (ADC)
	UDZO	compressed
	UDBZ	compressed (bzip2), deprecated
	ULFO	compressed (lzfse)
	ULMO	compressed (lzma)
	UFBI	entire device
	IPOD	iPod image
